    b.append('<div class="atlas">'+"".join(f'<a class="atl" href="{h if h!="maps.html" else ""}#{i}"><span>{ic}</span><b>{t}</b><small>{h.replace(".html","")}</small></a>' for i,h,ic,t in cards)+'</div>')
