    b.append('<h3 id="m6b">💰 福音书里的钱</h3>'+tbl(["币值","大约价值","经文"],MONEY))
    b.append('<h2 id="m7">🛰️ 七、底图来源与离线保障</h2><div class="flow">'+"".join(f'<div class="fstep"><span class="n">{k+1}</span>{t}</div>'+('<i class="farr">➜</i>' if k<4 else '') for k,t in enumerate(["滑到地图附近（IntersectionObserver）","载入本站自带的 Leaflet（无 CDN）","使用该图的首选底图","8 秒无瓦片或连续出错 → 自动换下一个底图","全部失败 → 显示提示，讲解图照常可用"]))+'</div>')
    b.append(tbl(["底图","说明","适合"],[[f"**{a}**",c,d] for a,c,d in PROV]))
    b.append('<p class="note">'+md("底图版权分别属于 OpenStreetMap 贡献者、Esri 及其数据提供方、OpenTopoMap、DARE（Johan Åhlfeldt，哥德堡大学）与高德；地图右下角会显示当前底图署名。Stadia/Stamen 与 CARTO 底图现需账号密钥（2026 年实测返回「API KEY REQUIRED」），本站未使用。")+'</p>')
    return "".join(b)
